toolCall.argumentsJson:
{"CommandLine":"$queries = @(
    "Ubiquiti-App",
    "UISP-Plugins",
    "UNMS-Plugins",
    "ubiquiti mikrotik",
    "ubnt mikrotik",
    "airos backup",
    "ubnt ssh",
    "airmax snmp"
)
foreach ($q in $queries) {
    Write-Host "=== QUERY: $q ==="
    $url = "https://api.github.com/search/repositories?q=$([uri]::EscapeDataString($q))&sort=stars&order=desc&per_page=6"
    try {
        $res = Invoke-RestMethod -Uri $url -Headers @{"User-Agent"="PowerShell"}
        foreach ($item in $res.items) {
            Write-Host "$($item.full_name) ($($item.stargazers_count) stars) - $($item.clone_url)"
        }
    } catch {
        Write-Host "Error: $_"
    }
    Start-Sleep -Milliseconds 700
}","WaitMsBeforeAsync":10000,"toolSummary":"Search additional GitHub repos for Ubiquiti-MikroTik and UISP"}
